// DATA PARSER - Limited to First 1000 Transactions
const csvData = $input.first().json.data;

console.log("=== DATA PARSER - LIMITED DATASET ===");
console.log(`Raw CSV length: ${csvData ? csvData.length : 0} characters`);

function parseTransactionCSV(csvText) {
  const lines = csvText.split('\n');
  const data = [];

  console.log(`Total CSV lines: ${lines.length}`);

  // LIMIT: Process only first 1000 transactions (plus header)
  const maxLines = Math.min(1001, lines.length); // Header + 1000 data rows

  for (let i = 1; i < maxLines; i++) {
    if (lines[i].trim()) {
      const values = lines[i].split(',').map(v => v.trim());
      if (values.length >= 17) {
        const transaction = {
          transaction_id: values[0] || `MISSING_ID_${i}`,
          sender_id: values[1] || '',
          sender_account_number: values[2] || '',
          sender_type: values[3] || '',
          sender_country: values[4] || '',
          sender_currency: values[5] || '',
          sender_amount: parseFloat(values[6]) || 0,
          recipient_id: values[7] || '',
          recipient_account_number: values[8] || '',
          recipient_type: values[9] || '',
          recipient_country: values[10] || '',
          recipient_currency: values[11] || '',
          recipient_amount: parseFloat(values[12]) || 0,
          transaction_date: values[13] || '',
          transaction_time: values[14] || '',
          source_of_funds: values[15] || '',
          payment_purpose: values[16] || '',

          // Computed fields
          multi_currency_flag: values[5] !== values[11],
          exchange_rate: parseFloat(values[6]) > 0 ? parseFloat(values[12]) / parseFloat(values[6]) : 1,

          // Data lineage
          row_number: i,
          parse_timestamp: new Date().toISOString(),
          data_source: 'google_sheets_limited'
        };
        data.push(transaction);
      }
    }
  }

  console.log(`✅ LIMITED DATASET: Successfully parsed ${data.length} transactions (out of ${lines.length-1} total)`);
  console.log(`Transaction ID range: ${data[0]?.transaction_id} to ${data[data.length-1]?.transaction_id}`);

  return data;
}

const transactions = parseTransactionCSV(csvData);

// Validation
if (transactions.length === 0) {
  console.error("⚠️ NO TRANSACTIONS PARSED - Check CSV format");
} else if (transactions.length > 1000) {
  console.log(`⚠️ Dataset limited to first 1000 transactions (was ${transactions.length})`);
}

return transactions.map((transaction, index) => ({ 
  json: { 
    ...transaction,
    processing_order: index + 1
  } 
}));

// FRM Configuration Setup
const sanctionedCountries = ['AFG', 'CAF', 'COD', 'IRN', 'IRQ', 'LBN', 'LBY', 'MLI', 'PRK', 'SOM', 'SSD', 'SDN', 'YEM', 'GNB'];
const highRiskSources = ['Cryptocurrency trading', 'Donation', 'Gambling'];

// Rule scoring weights (configurable)
const rules = {
  senderCountrySanctioned: { weight: 100, description: "Sender country in sanction list" },
  recipientCountrySanctioned: { weight: 100, description: "Recipient country in sanction list" },
  restrictedSourceFunds: { weight: 20, description: "Source of funds restricted" },
  highFrequencyTransactions: { weight: 20, description: "High frequency transactions" },
  highValueTransactions: { weight: 10, description: "High value transactions" },
  multiCurrencyTransfers: { weight: 10, description: "Multi-currency transfers to same recipient" }
};

// Decision thresholds (configurable)
const thresholds = {
  fraud: 50,        // >= 50 = Fraud (1)
  humanReview: 20,  // 20-49 = Human Review  
  notFraud: 20      // < 20 = Not Fraud (0)
};

console.log("Configuration loaded - Sanctioned countries:", sanctionedCountries.length);

return [{ 
  json: { 
    sanctionedCountries, 
    highRiskSources, 
    rules, 
    thresholds, 
    configured: true 
  } 
}];

// ENHANCED RULE ENGINE - Same as 10 Transaction Version
console.log("=== ENHANCED RULE ENGINE ===");

const allInputs = $input.all();
console.log(`Rule engine received: ${allInputs.length} transactions`);

const transactions = allInputs.map(item => item.json);

// Configuration (same as before)
const sanctionedCountries = ['AFG', 'CAF', 'COD', 'IRN', 'IRQ', 'LBN', 'LBY', 'MLI', 'PRK', 'SOM', 'SSD', 'SDN', 'YEM', 'GNB'];
const highRiskSources = ['Cryptocurrency trading', 'Donation', 'Gambling'];

// Enhanced rules with same weights as before
const enhancedRules = {
  senderCountrySanctioned: { weight: 100, description: "Sender country in sanction list" },
  recipientCountrySanctioned: { weight: 100, description: "Recipient country in sanction list" },
  restrictedSourceFunds: { weight: 20, description: "Source of funds restricted" },
  currencyLayering: { weight: 25, description: "Multi-currency layering pattern" },
  highFrequencyPattern: { weight: 20, description: "High frequency pattern analysis" },
  highValuePattern: { weight: 15, description: "High value concentration pattern" },
  roundAmountPattern: { weight: 10, description: "Suspicious round amount patterns" },
  velocityPattern: { weight: 15, description: "Unusual velocity patterns" }
};

const patternThresholds = {
  minCurrencies: 3,
  minTransactions: 3,
  timeWindowDays: 30,
  highFrequencyDaily: 5,
  highFrequencyWeekly: 10,
  highValueDaily: 100000,
  highValueWeekly: 500000,
  roundAmountThreshold: 0.95
};

// Helper function: Calculate date difference in days
function getDaysDifference(date1Str, date2Str) {
  try {
    const date1 = new Date(date1Str);
    const date2 = new Date(date2Str);
    return Math.abs((date2 - date1) / (1000 * 60 * 60 * 24));
  } catch (e) {
    return 0;
  }
}

// 1. Multi-currency layering detection (SAME AS BEFORE)
function analyzeMultiCurrencyLayering(transactions, currentTx) {
  const senderRecipientPairs = transactions.filter(tx => 
    tx.sender_id === currentTx.sender_id && 
    tx.recipient_id === currentTx.recipient_id &&
    getDaysDifference(tx.transaction_date, currentTx.transaction_date) <= patternThresholds.timeWindowDays
  );

  if (senderRecipientPairs.length < patternThresholds.minTransactions - 1) {
    return { triggered: false, details: null };
  }

  const allTransactions = [...senderRecipientPairs, currentTx];
  const currenciesUsed = new Set();

  allTransactions.forEach(tx => {
    currenciesUsed.add(tx.sender_currency);
    if (tx.sender_currency !== tx.recipient_currency) {
      currenciesUsed.add(tx.recipient_currency);
    }
  });

  if (currenciesUsed.size >= patternThresholds.minCurrencies) {
    return {
      triggered: true,
      details: {
        currencies: Array.from(currenciesUsed),
        transaction_count: allTransactions.length,
        sender_recipient_pair: `${currentTx.sender_id}→${currentTx.recipient_id}`,
        time_span_days: Math.max(...allTransactions.map(tx => 
          getDaysDifference(allTransactions[0].transaction_date, tx.transaction_date)
        ))
      }
    };
  }

  return { triggered: false, details: null };
}

// 2. High frequency pattern analysis (SAME AS BEFORE)
function analyzeFrequencyPatterns(transactions, currentTx) {
  const currentDate = currentTx.transaction_date;

  const sameDayTxns = transactions.filter(tx =>
    tx.sender_id === currentTx.sender_id &&
    tx.transaction_date === currentDate
  );

  const weeklyTxns = transactions.filter(tx =>
    tx.sender_id === currentTx.sender_id &&
    getDaysDifference(tx.transaction_date, currentDate) <= 7
  );

  const uniqueRecipients = new Set(weeklyTxns.map(tx => tx.recipient_id)).size;
  const avgTxnPerRecipient = weeklyTxns.length / uniqueRecipients;

  if (sameDayTxns.length > patternThresholds.highFrequencyDaily || 
      weeklyTxns.length > patternThresholds.highFrequencyWeekly ||
      (uniqueRecipients >= 5 && avgTxnPerRecipient >= 2)) {

    return {
      triggered: true,
      details: {
        daily_count: sameDayTxns.length,
        weekly_count: weeklyTxns.length,
        unique_recipients: uniqueRecipients,
        velocity_flag: uniqueRecipients >= 5 && avgTxnPerRecipient >= 2,
        pattern_type: uniqueRecipients >= 5 ? 'fan_out_pattern' : 'high_frequency'
      }
    };
  }

  return { triggered: false, details: null };
}

// 3. High value concentration analysis (SAME AS BEFORE)
function analyzeValuePatterns(transactions, currentTx) {
  const currentDate = currentTx.transaction_date;

  const sameDayTxns = transactions.filter(tx =>
    tx.sender_id === currentTx.sender_id &&
    tx.transaction_date === currentDate
  );

  const weeklyTxns = transactions.filter(tx =>
    tx.sender_id === currentTx.sender_id &&
    getDaysDifference(tx.transaction_date, currentDate) <= 7
  );

  const dailyTotal = sameDayTxns.reduce((sum, tx) => sum + (tx.sender_amount || 0), 0);
  const weeklyTotal = weeklyTxns.reduce((sum, tx) => sum + (tx.sender_amount || 0), 0);

  const justUnderThreshold = sameDayTxns.filter(tx => 
    tx.sender_amount >= 9000 && tx.sender_amount < 10000
  ).length;

  if (dailyTotal > patternThresholds.highValueDaily || 
      weeklyTotal > patternThresholds.highValueWeekly ||
      justUnderThreshold >= 3) {

    return {
      triggered: true,
      details: {
        daily_total: dailyTotal,
        weekly_total: weeklyTotal,
        structuring_flag: justUnderThreshold >= 3,
        just_under_threshold_count: justUnderThreshold,
        pattern_type: justUnderThreshold >= 3 ? 'structuring' : 'high_value'
      }
    };
  }

  return { triggered: false, details: null };
}

// 4. Round amount pattern detection (SAME AS BEFORE)
function analyzeRoundAmountPatterns(transactions, currentTx) {
  const senderTxns = transactions.filter(tx =>
    tx.sender_id === currentTx.sender_id &&
    getDaysDifference(tx.transaction_date, currentTx.transaction_date) <= patternThresholds.timeWindowDays
  );

  if (senderTxns.length < 3) return { triggered: false, details: null };

  const roundAmounts = senderTxns.filter(tx => {
    const amount = tx.sender_amount || 0;
    return (amount % 100 === 0) || (amount % 1000 === 0) || (amount % 10000 === 0);
  });

  const roundAmountRatio = roundAmounts.length / senderTxns.length;

  if (roundAmountRatio >= patternThresholds.roundAmountThreshold && roundAmounts.length >= 3) {
    return {
      triggered: true,
      details: {
        total_transactions: senderTxns.length,
        round_amount_transactions: roundAmounts.length,
        round_amount_percentage: (roundAmountRatio * 100).toFixed(1),
        sample_amounts: roundAmounts.slice(0, 5).map(tx => tx.sender_amount)
      }
    };
  }

  return { triggered: false, details: null };
}

// Main Enhanced Scoring Function (SAME AS BEFORE)
function calculateEnhancedRuleScore(transaction, allTransactions) {
  let score = 0;
  let triggeredRules = [];
  let patternDetails = {};

  // Rule 1: Sender country sanctioned (100 points)
  const senderCountry = transaction.sender_country || '';
  if (sanctionedCountries.includes(senderCountry)) {
    score += enhancedRules.senderCountrySanctioned.weight;
    triggeredRules.push(`Sender country sanctioned: ${senderCountry}`);
  }

  // Rule 2: Recipient country sanctioned (100 points)
  const recipientCountry = transaction.recipient_country || '';
  if (sanctionedCountries.includes(recipientCountry)) {
    score += enhancedRules.recipientCountrySanctioned.weight;
    triggeredRules.push(`Recipient country sanctioned: ${recipientCountry}`);
  }

  // Rule 3: High risk source of funds (20 points)
  const sourceOfFunds = transaction.source_of_funds || '';
  if (sourceOfFunds && highRiskSources.some(risk => 
    sourceOfFunds.toLowerCase().includes(risk.toLowerCase())
  )) {
    score += enhancedRules.restrictedSourceFunds.weight;
    triggeredRules.push(`High risk source: ${sourceOfFunds}`);
  }

  // Rule 4: ENHANCED Multi-currency layering (25 points)
  const currencyLayering = analyzeMultiCurrencyLayering(allTransactions, transaction);
  if (currencyLayering.triggered) {
    score += enhancedRules.currencyLayering.weight;
    triggeredRules.push(
      `Currency layering: ${currencyLayering.details.sender_recipient_pair} ` +
      `using ${currencyLayering.details.currencies.length} currencies`
    );
    patternDetails.currency_layering = currencyLayering.details;
  }

  // Rule 5: ENHANCED High frequency patterns (20 points)
  const frequencyPattern = analyzeFrequencyPatterns(allTransactions, transaction);
  if (frequencyPattern.triggered) {
    score += enhancedRules.highFrequencyPattern.weight;
    const details = frequencyPattern.details;
    triggeredRules.push(
      `${details.pattern_type}: ${details.daily_count} daily, ${details.weekly_count} weekly`
    );
    patternDetails.frequency_pattern = details;
  }

  // Rule 6: ENHANCED High value patterns (15 points)
  const valuePattern = analyzeValuePatterns(allTransactions, transaction);
  if (valuePattern.triggered) {
    score += enhancedRules.highValuePattern.weight;
    const details = valuePattern.details;
    triggeredRules.push(
      `${details.pattern_type}: Daily ${details.daily_total.toLocaleString()}`
    );
    patternDetails.value_pattern = details;
  }

  // Rule 7: Round amount patterns (10 points)
  const roundAmountPattern = analyzeRoundAmountPatterns(allTransactions, transaction);
  if (roundAmountPattern.triggered) {
    score += enhancedRules.roundAmountPattern.weight;
    const details = roundAmountPattern.details;
    triggeredRules.push(
      `Round amounts: ${details.round_amount_percentage}%`
    );
    patternDetails.round_amount_pattern = details;
  }

  return { score, triggeredRules, patternDetails };
}

// Process all transactions with enhanced analysis (SAME AS BEFORE)
const results = [];
for (const transaction of transactions) {
  const enhancedResult = calculateEnhancedRuleScore(transaction, transactions);

  // Apply decision matrix
  let decision, binary_value;
  if (enhancedResult.score >= 50) {
    decision = "Fraud";
    binary_value = 1;
  } else if (enhancedResult.score >= 20) {
    decision = "Human Review";
    binary_value = 0.5;
  } else {
    decision = "Not Fraud";
    binary_value = 0;
  }

  results.push({
    ...transaction,
    rule_score: enhancedResult.score,
    triggered_rules: enhancedResult.triggeredRules,
    pattern_details: enhancedResult.patternDetails,
    rule_decision: decision,
    rule_binary: binary_value,
    workflow: "enhanced_rule_based",
    analysis_timestamp: new Date().toISOString()
  });
}

console.log(`Rule engine processed: ${results.length} transactions`);
console.log(`Pattern Detection: ${results.filter(r => Object.keys(r.pattern_details).length > 0).length} transactions with detected patterns`);

return results.map(item => ({ json: item }));

