// Simple JavaScript ML Alternative - No Python Dependencies
const transactions = $input.all().map(item => item.json);

console.log("=== SIMPLE ML ENGINE ===");
console.log(`Processing ${transactions.length} transactions`);

// Calculate risk features for each transaction
function calculateRiskFeatures(transaction) {
  const features = {};

  // Amount-based features
  features.amount_risk = Math.min(100, Math.log10(transaction.sender_amount || 1) * 10);
  features.exchange_rate_risk = Math.abs(1 - (transaction.exchange_rate || 1)) * 100;

  // Country risk (simplified)
  const highRiskCountries = ['CAF', 'AFG', 'IRN', 'PRK', 'SOM', 'SDN', 'YEM'];
  features.country_risk = (
    (highRiskCountries.includes(transaction.sender_country) ? 50 : 0) +
    (highRiskCountries.includes(transaction.recipient_country) ? 50 : 0)
  );

  // Cross-border risk
  features.cross_border = transaction.sender_country !== transaction.recipient_country ? 20 : 0;

  // Multi-currency risk
  features.multi_currency = transaction.multi_currency_flag ? 15 : 0;

  // Entity type risk
  const entityRisk = {
    'Individual': 5, 'Partnership': 10, 'Corporation': 15, 
    'Foundation': 25, 'Trust': 20
  };
  features.entity_risk = (
    (entityRisk[transaction.sender_type] || 5) + 
    (entityRisk[transaction.recipient_type] || 5)
  );

  return features;
}

// Process transactions
const results = [];
const allScores = [];

for (const transaction of transactions) {
  const features = calculateRiskFeatures(transaction);

  // Simple ML score calculation (weighted sum)
  const ml_score = Math.min(100, Math.max(0,
    features.amount_risk * 0.3 +
    features.country_risk * 0.4 +
    features.exchange_rate_risk * 0.1 +
    features.cross_border * 0.1 +
    features.multi_currency * 0.05 +
    features.entity_risk * 0.05
  ));

  allScores.push(ml_score);

  // Decision logic
  let ml_decision, ml_binary;
  if (ml_score >= 70) {
    ml_decision = "Fraud";
    ml_binary = 1;
  } else if (ml_score >= 35) {
    ml_decision = "Human Review";
    ml_binary = 0.5;
  } else {
    ml_decision = "Not Fraud";
    ml_binary = 0;
  }

  const result = {
    ...transaction,
    ml_score: Math.round(ml_score * 100) / 100,
    ml_decision: ml_decision,
    ml_binary: ml_binary,
    ml_features: features,
    workflow: 'machine_learning'
  };

  results.push(result);

  console.log(`${transaction.transaction_id}: ML Score=${ml_score.toFixed(2)}, Decision=${ml_decision}`);
}

// Summary stats
const avgScore = allScores.reduce((a, b) => a + b, 0) / allScores.length;
console.log(`\n=== ML SUMMARY ===`);
console.log(`Average ML Score: ${avgScore.toFixed(2)}`);
console.log(`Fraud Cases: ${results.filter(r => r.ml_decision === "Fraud").length}`);
console.log(`Review Cases: ${results.filter(r => r.ml_decision === "Human Review").length}`);

return results.map(item => ({ json: item }));

