// ML Results Debug
const results = $input.all().map(item => item.json);

console.log("=== ML RESULTS DEBUG ===");
console.log(`Total ML results: ${results.length}`);

// Show each transaction's ML results
results.forEach((result, index) => {
  console.log(`\n${index + 1}. ${result.transaction_id || 'Unknown ID'}`);
  console.log(`   ML Score: ${result.ml_score}`);
  console.log(`   ML Decision: ${result.ml_decision}`);
  console.log(`   Features Used: ${result.ml_features_used}`);
});

// Summary stats
const mlScores = results.map(r => r.ml_score).filter(s => s !== undefined);
if (mlScores.length > 0) {
  console.log(`\n=== ML SCORE SUMMARY ===`);
  console.log(`Min Score: ${Math.min(...mlScores)}`);
  console.log(`Max Score: ${Math.max(...mlScores)}`);
  console.log(`Average: ${(mlScores.reduce((a, b) => a + b, 0) / mlScores.length).toFixed(2)}`);
}

return results.map(item => ({ json: item }));

// CONVERGENCE: Aggregate Rule-based and ML Scores
console.log("=== CONVERGENCE ENGINE ===");

const allResults = $input.all().map(item => item.json);
const transactionMap = new Map();

console.log(`Processing ${allResults.length} results from both engines`);

// Group results by transaction ID
for (const result of allResults) {
  const txId = result.transaction_id;

  if (!transactionMap.has(txId)) {
    transactionMap.set(txId, {});
  }

  const existing = transactionMap.get(txId);
  transactionMap.set(txId, { ...existing, ...result });
}

console.log(`Unique transactions found: ${transactionMap.size}`);

// Configurable aggregation weights
const aggregationWeights = {
  ruleWeight: 0.6,    // 60% weight to rule-based
  mlWeight: 0.4       // 40% weight to ML
};

// Configurable aggregate thresholds
const aggregateThresholds = {
  fraud: 60,          // >= 60 = Fraud
  humanReview: 25     // 25-59 = Human Review
};

const results = [];

// Calculate aggregate scores
for (const [txId, transaction] of transactionMap) {
  const ruleScore = transaction.rule_score || 0;
  const mlScore = transaction.ml_score || 0;

  // Weighted aggregation
  const aggregateScore = (ruleScore * aggregationWeights.ruleWeight) + 
                        (mlScore * aggregationWeights.mlWeight);

  // Final decision matrix
  let finalDecision, finalBinary;

  if (aggregateScore >= aggregateThresholds.fraud) {
    finalDecision = "Fraud";
    finalBinary = 1;
  } else if (aggregateScore >= aggregateThresholds.humanReview) {
    finalDecision = "Human Review";
    finalBinary = 0.5;
  } else {
    finalDecision = "Not Fraud";
    finalBinary = 0;
  }

  const finalResult = {
    ...transaction,
    // Keep individual scores
    rule_score: ruleScore,
    ml_score: mlScore,
    // Add aggregate results
    aggregate_score: Math.round(aggregateScore * 100) / 100,
    final_decision: finalDecision,
    final_binary: finalBinary,
    final_score: aggregateScore,
    // Add metadata
    rule_weight_used: aggregationWeights.ruleWeight,
    ml_weight_used: aggregationWeights.mlWeight,
    processing_timestamp: new Date().toISOString()
  };

  results.push(finalResult);

  console.log(`${txId}: Rule=${ruleScore}, ML=${mlScore}, Final=${aggregateScore.toFixed(2)} → ${finalDecision}`);
}

// Summary
const fraudCount = results.filter(r => r.final_decision === "Fraud").length;
const reviewCount = results.filter(r => r.final_decision === "Human Review").length;
const notFraudCount = results.filter(r => r.final_decision === "Not Fraud").length;

console.log("\n=== FINAL DECISIONS ===");
console.log(`Fraud: ${fraudCount}, Human Review: ${reviewCount}, Not Fraud: ${notFraudCount}`);

return results.map(item => ({ json: item }));

// FINAL FRM SYSTEM SUMMARY
const results = $input.all().map(item => item.json);

console.log("=== FRM SYSTEM FINAL RESULTS ===");
console.log(`Total transactions processed: ${results.length}`);

// Create summary report
const summary = {
  total_transactions: results.length,
  decisions: {
    fraud: results.filter(r => r.final_decision === "Fraud").length,
    human_review: results.filter(r => r.final_decision === "Human Review").length, 
    not_fraud: results.filter(r => r.final_decision === "Not Fraud").length
  },
  average_scores: {
    rule_avg: (results.reduce((sum, r) => sum + (r.rule_score || 0), 0) / results.length).toFixed(2),
    ml_avg: (results.reduce((sum, r) => sum + (r.ml_score || 0), 0) / results.length).toFixed(2),
    aggregate_avg: (results.reduce((sum, r) => sum + (r.aggregate_score || 0), 0) / results.length).toFixed(2)
  }
};

console.log("\n=== DECISION BREAKDOWN ===");
console.log(`Fraud Cases: ${summary.decisions.fraud}`);
console.log(`Human Review: ${summary.decisions.human_review}`);
console.log(`Not Fraud: ${summary.decisions.not_fraud}`);

console.log("\n=== SCORE AVERAGES ===");
console.log(`Average Rule Score: ${summary.average_scores.rule_avg}`);
console.log(`Average ML Score: ${summary.average_scores.ml_avg}`);
console.log(`Average Final Score: ${summary.average_scores.aggregate_avg}`);

console.log("\n=== HIGH RISK TRANSACTIONS ===");
results.filter(r => r.final_decision === "Fraud").forEach(r => {
  console.log(`🚨 ${r.transaction_id}: ${r.sender_country}→${r.recipient_country}, Score: ${r.aggregate_score}`);
  console.log(`   Rules: [${r.triggered_rules?.join(', ') || 'None'}]`);
});

// Return results with summary
return results.map(item => ({ 
  json: { 
    ...item, 
    system_summary: summary 
  } 
}));

// HUMAN REVIEW PROCESSOR
console.log("=== HUMAN REVIEW PROCESSOR ===");

// Get human labels from webhook (expecting CSV or JSON format)
const humanInput = $input.first().json;
console.log("Human review input received:", humanInput);

// Example expected format:
// [
//   {"transaction_id": "TXN00000001", "human_label": 0},
//   {"transaction_id": "TXN00000002", "human_label": 1}
// ]

// Parse human labels if CSV format
function parseHumanLabels(input) {
  if (typeof input === 'string') {
    // Parse CSV format
    const lines = input.split('\n');
    const labels = [];

    for (let i = 1; i < lines.length; i++) { // Skip header
      if (lines[i].trim()) {
        const [txId, label] = lines[i].split(',').map(s => s.trim());
        labels.push({
          transaction_id: txId,
          human_label: parseInt(label) || 0
        });
      }
    }
    return labels;
  }

  // Assume JSON format
  return Array.isArray(input) ? input : [input];
}

const humanLabels = parseHumanLabels(humanInput);
console.log(`Processed ${humanLabels.length} human labels`);

// Store for later use in performance analysis
return humanLabels.map(label => ({ json: label }));

// ENHANCED PERFORMANCE ANALYSIS - Handles Both System & Human Inputs
console.log("=== ENHANCED PERFORMANCE ANALYSIS ===");

// Get system results
const systemResults = $('Final FRM Report').all().map(item => item.json);
console.log(`System results: ${systemResults.length} transactions`);

// Get human labels (if available)
let humanLabels = [];
try {
  // Try to get human labels from second input
  const humanInput = $('Process Human labels').all();
  if (humanInput && humanInput.length > 0) {
    humanLabels = humanInput.map(item => item.json);
    console.log(`Human labels received: ${humanLabels.length}`);
  }
} catch (e) {
  console.log("No human labels provided, using demo data");
}

// If no human labels, use demo data based on your scores
