// Enhanced feature extraction with behavioral analysis (SAME AS BEFORE)
function extractAdvancedFeatures(transaction, allTransactions) {
  const features = {};

  // === BASIC FEATURES ===

  // Amount features (log-normalized)
  features.amount_log = Math.log10(Math.max(1, transaction.sender_amount || 0));
  features.recipient_amount_log = Math.log10(Math.max(1, transaction.recipient_amount || 0));
  features.amount_ratio = (transaction.recipient_amount || 0) / Math.max(1, transaction.sender_amount || 0);

  // === TEMPORAL FEATURES ===
  try {
    const txDate = new Date(`${transaction.transaction_date} ${transaction.transaction_time}`);
    features.hour = txDate.getHours();
    features.day_of_week = txDate.getDay();
    features.is_weekend = (features.day_of_week === 0 || features.day_of_week === 6) ? 1 : 0;
    features.is_night = (features.hour >= 22 || features.hour <= 6) ? 1 : 0;
    features.is_business_hours = (features.hour >= 9 && features.hour <= 17) ? 1 : 0;
  } catch (e) {
    features.hour = 12; 
    features.day_of_week = 1; 
    features.is_weekend = 0;
    features.is_night = 0; 
    features.is_business_hours = 1;
  }

  // === BEHAVIORAL FEATURES ===

  // Sender behavior analysis
  const senderHistory = allTransactions.filter(t => t.sender_id === transaction.sender_id);
  features.sender_tx_count = senderHistory.length;
  features.sender_unique_recipients = new Set(senderHistory.map(t => t.recipient_id)).size;
  features.sender_avg_amount = senderHistory.length > 0 ? 
    senderHistory.reduce((sum, t) => sum + (t.sender_amount || 0), 0) / senderHistory.length : 0;

  // Amount deviation from sender's normal behavior
  features.amount_z_score = features.sender_avg_amount > 0 ? 
    Math.abs((transaction.sender_amount || 0) - features.sender_avg_amount) / features.sender_avg_amount : 0;

  // Recipient behavior analysis
  const recipientHistory = allTransactions.filter(t => t.recipient_id === transaction.recipient_id);
  features.recipient_popularity = recipientHistory.length;
  features.recipient_avg_received = recipientHistory.length > 0 ?
    recipientHistory.reduce((sum, t) => sum + (t.recipient_amount || 0), 0) / recipientHistory.length : 0;

  // Relationship analysis
  const relationship = senderHistory.filter(t => t.recipient_id === transaction.recipient_id);
  features.is_new_relationship = relationship.length <= 1 ? 1 : 0;
  features.relationship_frequency = relationship.length;

  // === PATTERN FEATURES ===

  // Amount patterns
  features.is_round_amount = ((transaction.sender_amount || 0) % 1000 === 0) ? 1 : 0;
  features.amount_digit_count = (transaction.sender_amount || 0).toString().replace('.', '').length;

  // Geographic features
  features.is_cross_border = (transaction.sender_country !== transaction.recipient_country) ? 1 : 0;
  features.is_multi_currency = (transaction.sender_currency !== transaction.recipient_currency) ? 1 : 0;

  // Entity risk encoding
  const entityRisk = {'Individual': 1, 'Partnership': 2, 'Corporation': 3, 'Foundation': 4, 'Trust': 5};
  features.sender_entity_risk = entityRisk[transaction.sender_type] || 1;
  features.recipient_entity_risk = entityRisk[transaction.recipient_type] || 1;
  features.entity_risk_combination = features.sender_entity_risk + features.recipient_entity_risk;

  // Country risk (enhanced)
  const highRiskCountries = ['AFG', 'CAF', 'COD', 'IRN', 'IRQ', 'LBN', 'LBY', 'MLI', 'PRK', 'SOM', 'SSD', 'SDN', 'YEM', 'GNB'];
  features.sender_country_risk = highRiskCountries.includes(transaction.sender_country) ? 1 : 0;
  features.recipient_country_risk = highRiskCountries.includes(transaction.recipient_country) ? 1 : 0;

  // Source of funds risk
  const highRiskSources = ['cryptocurrency', 'donation', 'gambling'];
  features.source_risk = highRiskSources.some(risk => 
    (transaction.source_of_funds || '').toLowerCase().includes(risk)) ? 1 : 0;

  return features;
}

// JavaScript-based Isolation Forest Algorithm (SAME AS BEFORE)
class JavaScriptIsolationForest {
  constructor(nTrees = 50, contamination = 0.15) {
    this.nTrees = nTrees;
    this.contamination = contamination;
    this.trees = [];
    this.featureNames = [];
  }

  fit(data) {
    this.featureNames = Object.keys(data[0]);
    console.log(`Training Isolation Forest with ${this.nTrees} trees on ${this.featureNames.length} features`);

    for (let i = 0; i < this.nTrees; i++) {
      const sampleSize = Math.min(256, data.length);
      const sample = this.randomSample(data, sampleSize);
      this.trees.push(this.buildTree(sample, 0, Math.ceil(Math.log2(sampleSize))));
    }

    console.log(`Isolation Forest training completed`);
  }

  randomSample(data, size) {
    const sample = [];
    for (let i = 0; i < size; i++) {
      sample.push(data[Math.floor(Math.random() * data.length)]);
    }
    return sample;
  }

  buildTree(data, depth, maxDepth) {
    if (depth >= maxDepth || data.length <= 1 || this.allSame(data)) {
      return { isLeaf: true, size: data.length };
    }

    const feature = this.featureNames[Math.floor(Math.random() * this.featureNames.length)];
    const values = data.map(d => d[feature]).filter(v => v !== undefined && !isNaN(v));

    if (values.length === 0) {
      return { isLeaf: true, size: data.length };
    }

    const min = Math.min(...values);
    const max = Math.max(...values);

    if (min === max) {
      return { isLeaf: true, size: data.length };
    }

    const splitPoint = min + Math.random() * (max - min);

    const left = data.filter(d => (d[feature] || 0) < splitPoint);
    const right = data.filter(d => (d[feature] || 0) >= splitPoint);

    return {
      isLeaf: false,
      feature: feature,
      splitPoint: splitPoint,
      left: this.buildTree(left, depth + 1, maxDepth),
      right: this.buildTree(right, depth + 1, maxDepth)
    };
  }

  allSame(data) {
    if (data.length <= 1) return true;
    const first = data[0];
    return data.every(d => 
      this.featureNames.every(f => d[f] === first[f])
    );
  }

  predict(data) {
    return data.map(point => this.getAnomalyScore(point));
  }

  getAnomalyScore(point) {
    let totalPathLength = 0;

    for (let tree of this.trees) {
      totalPathLength += this.getPathLength(point, tree, 0);
    }

    const avgPathLength = totalPathLength / this.trees.length;
    const c = this.cFactor(256);

    return Math.pow(2, -avgPathLength / c);
  }

  getPathLength(point, tree, depth) {
    if (tree.isLeaf) {
      return depth + this.cFactor(tree.size);
    }

    const featureValue = point[tree.feature] || 0;
    if (featureValue < tree.splitPoint) {
      return this.getPathLength(point, tree.left, depth + 1);
    } else {
      return this.getPathLength(point, tree.right, depth + 1);
    }
  }

  cFactor(n) {
    if (n <= 1) return 0;
    return 2 * (Math.log(n - 1) + 0.5772156649) - (2 * (n - 1)) / n;
  }
}

// Statistical outlier detection (SAME AS BEFORE)
function calculateStatisticalOutlier(features, allFeatures) {
  let outlierScore = 0;
  const featureNames = Object.keys(features);

  for (let feature of featureNames) {
    if (typeof features[feature] === 'number') {
      const values = allFeatures.map(f => f[feature]).filter(v => !isNaN(v));
      if (values.length > 1) {
        const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
        const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
        const stdDev = Math.sqrt(variance);

        if (stdDev > 0) {
          const zScore = Math.abs((features[feature] - mean) / stdDev);
          outlierScore += Math.min(zScore / 3, 1);
        }
      }
    }
  }

  return Math.min(outlierScore / featureNames.length, 1);
}

